package main

import (
	"context"
	"flag"
	"os"
	"os/signal"

	"legagent/app/services"
)

// runInitNews 建立新聞索引的 PostgreSQL 資料表。
//
//	go run . init-news
//
// @ai:generated by=claude-opus-5-5 date=2026-11-06
// @ai:purpose 建表是明確的維運動作，與伺服器啟動和匯入腳本分開
// @ai:input args 子命令參數
// @ai:output none
// @ai:sideeffect 建立 news schema 與資料表、失敗時 os.Exit
func runInitNews(args []string) {
	fs := flag.NewFlagSet("init-news", flag.ExitOnError)
	cfgPath := fs.String("config", defaultConfigPath, "config.yaml 路徑")
	_ = fs.Parse(args)

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	cfg, log := mustLoad(*cfgPath)
	db := mustOpenDB(cfg, log)
	defer db.Close()

	if err := services.EnsureNewsSchema(ctx, db, log); err != nil {
		db.Close()
		os.Exit(1)
	}
	log.Info("news schema ready", "tables", len(services.NewsTables))
}
